function validate([start, finish, limit, s]) {
  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(finish) || start < 1 || start > finish || finish > 1e15) return 'Need whole numbers with 1 <= start <= finish <= 10^15.';
  if (!Number.isInteger(limit) || limit < 1 || limit > 9) return 'limit is a whole number from 1 to 9.';
  if (typeof s !== 'string' || !/^[1-9][0-9]*$/.test(s)) return 's must be digits with no leading zero.';
  if (s.length > String(finish).length) return 's cannot have more digits than finish.';
  if ([...s].some(ch => Number(ch) > limit)) return 'Every digit of s must be at most limit.';
  return null;
}

