function numberOfPowerfulInt(start, finish, limit, s) {
  const countUpTo = (x) => {
    const digits = String(x);
    const free = digits.length - s.length;
    if (free < 0) {
      return 0;
    }
    let below = 0;
    let tight = 1;
    for (let i = 0; i < free; i++) {
      const digit = Number(digits[i]);
      below = below * (limit + 1) + tight * Math.min(digit, limit + 1);
      if (digit > limit) {
        tight = 0;
      }
    }
    const tail = digits.slice(free);
    const tailFits = tight === 1 && tail >= s;
    return below + (tailFits ? 1 : 0);
  };
  return countUpTo(finish) - countUpTo(start - 1);
}

