function numberOfPowerfulInt(start, finish, limit, s) {
  // Every number ending with s is k * 10^len + s; walk the k values that land in range and test their digits.
  const step = 10 ** s.length;
  const tail = Number(s);
  let k = Math.max(0, Math.ceil((start - tail) / step));
  let total = 0;
  for (let x = k * step + tail; x <= finish; x += step) {
    if (x < start) continue;
    if ([...String(x)].every(ch => Number(ch) <= limit)) total++;
  }
  return total;
}

