function generate(rand, size) {
  const digitsUpTo = (top, first) => String(first ? 1 + Math.floor(rand() * top) : Math.floor(rand() * (top + 1)));
  const finishDigits = size === 'large' ? 10 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 6);
  let finish = Math.floor(rand() * 10 ** finishDigits) + 1;
  if (size === 'large' && rand() < 0.25) finish = 1000000000000000;
  const start = rand() < 0.3 ? 1 : 1 + Math.floor(rand() * finish);
  const limit = 1 + Math.floor(rand() * 9);
  const maxLength = String(finish).length;
  const length = 1 + Math.floor(rand() * Math.min(maxLength, size === 'large' ? 6 : maxLength));
  let s = digitsUpTo(limit, true);
  while (s.length < length) s += digitsUpTo(limit, false);
  return [start, finish, limit, s];
}
